// Twilio manda application/x-www-form-urlencoded, no JSON: sus webhooks de
// voz no tienen version JSON. n8n lo entrega en el campo body, asi que puede
// llegar ya parseado o como texto plano.
// Referencia de campos: docs de Twilio, recurso Call (estado de la llamada).

const crudo = $input.first().json.body ?? {};
const form = typeof crudo === 'string'
  ? Object.fromEntries(new URLSearchParams(crudo))
  : crudo;

const estado = form.CallStatus;

// 'completed' significa que alguien descolgo. Solo interesan las entrantes
// que se quedaron sin contestar.
const NO_ATENDIDAS = ['no-answer', 'busy', 'failed'];

return [{
  json: {
    missed: NO_ATENDIDAS.includes(estado),
    motivo: 'Twilio CallStatus=' + estado,
    telefono: form.From ?? '',
    clinica_id: 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
    nombre: null,
    proveedor: 'twilio',
    referencia: form.CallSid ?? null,
  },
}];

// Telnyx manda JSON con esta envoltura:
//   data.event_type, data.payload.from, data.payload.to,
//   data.payload.hangup_cause, data.payload.call_session_id
//
// ATENCION: que hangup_cause significa 'nadie descolgo' depende de como este
// configurada la conexion de la clinica. Antes de dar esto por bueno, haz una
// llamada de prueba y mira el evento real en Webhook Deliveries de tu cuenta
// de Telnyx. Si tu clinica devuelve otra causa, anadela a la lista de abajo.

const body = $input.first().json.body ?? {};
const data = body.data ?? {};
const payload = data.payload ?? {};

const evento = data.event_type ?? '';
const causa = payload.hangup_cause ?? '';

// Causas que, en la practica, son una llamada entrante sin contestar.
const CAUSAS_SIN_ATENDER = [
  'call_rejected',
  'no-answer',
  'no_answer',
  'unanswered',
];

const soloEntrante = payload.direction === 'incoming';

return [{
  json: {
    missed: evento === 'call.hangup' && soloEntrante && CAUSAS_SIN_ATENDER.includes(causa),
    motivo: 'Telnyx ' + evento + ' hangup_cause=' + causa + ' direction=' + payload.direction,
    telefono: payload.from ?? '',
    clinica_id: 'a1000000-0000-4000-8000-000000000000',
    nombre: null,
    proveedor: 'telnyx',
    referencia: payload.call_session_id ?? data.id ?? null,
  },
}];

// Contrato generico: el mismo que ya acepta el backend.
//   { clinica_id, telefono, nombre }
//
// Sirve para centralitas o CRM que ya envien JSON a medida, y es el punto de
// entrada cuando conectes algo nuevo: copia este bloque y adapta los nombres.

const body = $input.first().json.body ?? {};
const tel = body.telefono ?? body.from ?? body.From ?? body.phone ?? '';

return [{
  json: {
    missed: !!tel,
    motivo: 'Contrato generico',
    clinica_id: body.clinica_id ?? 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
    telefono: tel,
    nombre: body.nombre ?? body.name ?? null,
    proveedor: 'generico',
    referencia: null,
  },
}];

// Limpia el telefono antes de tocar la base de datos, para que el mismo
// paciente no acabe con dos fichas. La regla definitiva vive en utils.py del
// backend (normalizar_telefono); aqui solo se deja presentable para los logs.

function limpiar(valor) {
  const bruto = String(valor ?? '').trim();
  const digitos = bruto.replace(/\D/g, '');
  if (!digitos) return '';
  if (bruto.startsWith('00')) return '+' + digitos.slice(2);
  if (bruto.startsWith('+')) return '+' + digitos;
  if (digitos.length === 9 && '6789'.includes(digitos[0])) return '+34' + digitos;
  if (digitos.length > 9) return '+' + digitos;
  return digitos;
}

const j = $input.first().json;
const telefono = limpiar(j.telefono);

if (!telefono) {
  throw new Error('Llamada perdida sin telefono legible. Origen: ' + j.proveedor + ' / ' + j.motivo);
}

return [{ json: { ...j, telefono } }];
